import logging
import os
import stat

import taf.internal.robot_typecasts as robot_typecasts
from taf.internal.aliasing import aliasing_scope
from taf.internal.contracts import SshClientConfig, contract_consumer

from .cache import ConnectionCache, SessionCache
from .connection import Connection, FileProtocolClientError
from .keepalive import ensure_connection, keep_instance_connected
from .proxy_keys.key_fetch import KeyFetcher
from .session import SSHSession

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SSHManager:
    lookup_handler, store = aliasing_scope(
        name=__name__, lookup_arg="connection", lookup_type=(SSHSession, Connection)
    )

    # FIXME: to be deprecated - return value of connect to
    # FIXME: to be deprecated - usage of SSHConnection as connection=...

    def __init__(self):
        self.connection_cache = ConnectionCache
        self.session_cache = SessionCache

    @contract_consumer(
        robot_name="Connect to: ${contract_data: [^(]+} (aliased as ${alias})"
    )
    def configure_ssh_connection(self, contract_data: SshClientConfig, alias=None):
        def _connect(configuration, alias=None):
            if configuration["proxy"] is not None:
                proxy = _connect(configuration["proxy"], alias=alias)
            else:
                proxy = None
            return self.connect_to(
                hostname=configuration["addr"],
                username=configuration["username"],
                password=configuration["password"],
                port=configuration["port"],
                key_path=configuration["private_key"],
                proxy=proxy,
                alias=alias,
            )
        return _connect(contract_data, alias)

    @contract_consumer(
        robot_name="Connect to: ${contract_data: [^(]+} (aliased as ${alias}) via ${proxy}"
    )
    def configure_ssh_connection_via_proxy(
        self, contract_data: SshClientConfig, alias, proxy
    ):
        configuration = contract_data
        return self.connect_to(
            hostname=configuration["addr"],
            username=configuration["username"],
            password=configuration["password"],
            port=configuration["port"],
            key_path=configuration["private_key"],
            proxy=proxy,
            alias=alias,
        )

    def connect_to(
        self,
        hostname,
        username,
        password=None,
        port=None,
        key_path=None,
        proxy=None,
        alias=None,
        timeout=30.0,
        look_for_keys=True,
        allow_agent=True,
    ):
        """Create and initialize a connection to a remote.

        The proxy parameter should be, if it is given, an instance that
        inherits from Connection class, or a string containing its alias.
        The new connection will be routed through the given object.

        The new connection instance will be cached on a configuration basis.
        If an alias parameter is given, the instance will be also cached by
        it's value. If no alias is given, the instance alias will be set to
        'default'.

        The 'key_path' parameter specifies the path to key that should be used
        to authenticate with the remote.

        (from paramiko docs:)
        Authentication is attempted in the following order of priority:
            - The key_filename passed in (if any)
            - Any key we can find through an SSH agent
            - Any “id_rsa”, “id_dsa” or “id_ecdsa” key discoverable in ~/.ssh/
            - Plain username/password auth, if a password was given

        To disable searching for discoverable private key files in ~/.ssh/ set
        'look_for_keys' to False. To disable asking SSH Agent for them, set
        'allow_agent' to False.

        If the connection is tunneled through a proxy, the keyword will try to
        use any discoverable "id_rsa", "id_dsa" or "id_ecdsa" from the proxy
        first (but only the first one).

        If a private key requires a password to unlock it, and a password is
        passed in, that password will be used to attempt to unlock the key.
        """

        self._check_hostname_sanity(hostname)
        self._log_connection_request(username, hostname, port)

        timeout = robot_typecasts.time_to_seconds(timeout)
        if port is not None:
            port = int(port)

        connection_params = {
            "hostname": hostname,
            "username": username,
            "password": password,
            "port": port,
            "key_path": key_path,
            "timeout": timeout,
            "look_for_keys": look_for_keys,
            "allow_agent": allow_agent,
        }

        if proxy is not None:
            proxy = self._get_connection_object(proxy)

            logger.info("Connection will be routed through proxy: %s", proxy)

            keep_instance_connected(proxy)
            connection_params["proxy"] = proxy

            if look_for_keys:
                pkey = self._fetch_pkey_from_proxy(
                    proxy, hostname, password, timeout=timeout
                )
            else:
                pkey = None

            if pkey is not None:
                logger.info("Trying the key fetched from the proxy first.")
                connection_params["pkey"] = pkey

        connection = self.connection_cache.get_connection(**connection_params)
        session = SSHSession(connection)
        self.session_cache.cache_set(connection, session)
        self.store.add(session, alias)

        # FIXME: This should either return SSHSession or return nothing at all.
        # Returning nothing at all may finally push people into using the
        # right API.
        return connection

    @classmethod
    def _get_connection_object(cls, obj):
        """Return the correct Connection object for given object.

        For given value of obj:
        If it's an instance of SSHConnection / ProxySSHConnection / Connection:
            return proxy_parameter as is.
        If it's an instance of SSHSession:
            return its underlying connection object.
        If it's anything else:
            try to use it as an alias to store.get(), return the connection
            object of the session that was returned by the store. If the store
            returns a Connection, return it as is.
        """
        if isinstance(obj, SSHSession):
            return obj.connection
        if not isinstance(obj, Connection):
            session = cls.store.get(obj)

            # XXX: The store shouldn't really return Connection, ever. But if
            # it does, this code makes sure that if someone put a Connection
            # there, we don't get AttributeErrors.
            if isinstance(session, Connection):
                return session

            return session.connection

        return obj

    @staticmethod
    def _log_connection_request(username, hostname, port):
        if port is None:
            user_at_host = "{}@{}"
        else:
            user_at_host = "{}@{}:{}"
        user_at_host = user_at_host.format(username, hostname, port)
        logger.info("Requesting connection to %s.", user_at_host)

    @staticmethod
    def _check_hostname_sanity(hostname):
        insane = set("\"'/\\?!@#$%^&*()[]{}<>;,|=+\n\r")
        for pos, char in enumerate(hostname):
            if char not in insane:
                continue

            hostname = hostname.replace("\n", "<LF>")
            hostname = hostname.replace("\r", "<CR>")

            warn_msg = "Detected a special character in the hostname: \n"
            warn_msg += hostname + "\n"
            warn_msg += " " * pos + "^"
            logger.warning(warn_msg)
            break

    # TODO: whenever paramiko will have option to pass a list as pkey parameter
    # the '[0]' should be removed.
    def _fetch_pkey_from_proxy(self, proxy, target_host, password, timeout):
        logger.info("Fetching private keys from proxy host.")
        keys = KeyFetcher.fetch_keys(proxy, target_host, password, timeout=timeout)
        if keys:
            return keys[0]
        return None

    @lookup_handler.implicit_lookup
    def disconnect(self, connection=None):
        """Disconnect the given connection instance, and remove it from cache.

        Disconnects the connection object given, tries to find it in cache and
        removes it from there. Also tries to aliases to which this connection
        is binded to, unbinds it.
        """
        connection = self._get_session_of(connection)
        connection.disconnect()
        self.connection_cache.decache_object(
            self.session_cache.get_objects_key(connection)
        )
        self.session_cache.decache_object(connection)
        self.store.remove_object(connection)

    @lookup_handler.implicit_lookup
    @ensure_connection
    def send_command(
        self, command, bufsize=None, timeout=None, get_pty=False, connection=None
    ):
        """Send a command to the remote.

        Sends a command to the remote using the instance designated by the
        connection parameter.
        If a value of the connection parameter is a string, it is interpreted
        as an alias. If it is an object that inherits from Connection class
        (SSHConnection or ProxySSHConnection), then it is used to send the
        command as-is.

        If an unrecognized alias is given,
        taf.internal.aliasing.AliasingLookupError is raised

        If no value is given, the alias "default" is used.
        """
        connection = self._get_session_of(connection)
        timeout = robot_typecasts.time_to_seconds(timeout)
        get_pty = robot_typecasts.to_boolean(get_pty)

        logger.info("Sending a command: %r", command)
        if bufsize is not None:
            bufsize = int(bufsize)
        else:
            bufsize = -1
        connection.send_command(
            command, bufsize=bufsize, timeout=timeout, get_pty=get_pty
        )

    @lookup_handler.implicit_lookup
    @ensure_connection
    def execute(self, command, connection=None, timeout=None):
        """Carry out full execution of a command on the remote.

        Sends a command to the remote using the instance designated by the
        connection parameter, waits for the execution to finish, and returns
        the outputs' contents (both stdout and stdin).

        This will request a PTY on the remote, which has the effect of
        preserving the ordering of stdout and stderr lines.

        :param timeout: (optional) Timeout for keyword execution, None by
            default. Accepts a timeout string in Robot Framework format.
            If None, waits for the command to end indefinitely.
        """
        connection = self._get_session_of(connection)
        timeout = robot_typecasts.time_to_seconds(timeout)

        return connection.execute(command, timeout=timeout)

    @lookup_handler.implicit_lookup
    def read_output(self, size=None, connection=None):
        """Read stdout from the remote.

        See .send_command() for a documentation on the connection parameter.
        """
        connection = self._get_session_of(connection)
        if size is not None:
            size = int(size)
        output = connection.last_process.read_output(size=size)
        logger.info("Output: %r", output)
        return output

    @lookup_handler.implicit_lookup
    def write_input(self, data, flush=False, connection=None):
        """Write to remote's stdin

        See .send_command() for a documentation on the connection parameter.
        """
        connection = self._get_session_of(connection)
        flush = robot_typecasts.to_boolean(flush)

        logger.info("Sending input: %r", data)
        connection.last_process.write_input(data)
        if flush:
            connection.last_process.stdin.flush()

    @lookup_handler.implicit_lookup
    def read_error(self, size=None, connection=None):
        """Read stderr from the remote.

        See .send_command() for a documentation on the connection parameter.
        """
        connection = self._get_session_of(connection)
        if size is not None:
            size = int(size)
        errors = connection.last_process.read_error(size=size)
        logger.info("Error output: %r", errors)
        return errors

    @lookup_handler.implicit_lookup
    def read_output_until(self, match, timeout=None, connection=None):
        """Read stdout from the remote until a the given substring.

        See .send_command() for a documentation on the connection parameter.
        """
        connection = self._get_session_of(connection)
        timeout = robot_typecasts.time_to_seconds(timeout)

        self._log_read_until("standard output", match, timeout)
        output = connection.last_process.read_output_until(match, timeout)
        logger.info("Output: %r", output)
        return output

    @lookup_handler.implicit_lookup
    def read_error_until(self, match, timeout=None, connection=None):
        """Read stderr from the remote until a the given substring.

        See .send_command() for a documentation on the connection parameter.
        """
        connection = self._get_session_of(connection)
        timeout = robot_typecasts.time_to_seconds(timeout)

        self._log_read_until("standard error", match, timeout)
        errors = connection.last_process.read_error_until(match, timeout)
        logger.info("Error output: %r", errors)
        return errors

    @staticmethod
    def _log_read_until(channel_name, pattern, timeout):
        logger.info(
            "Reading %s until pattern %r. Timeout: %g seconds.",
            channel_name,
            pattern,
            timeout,
        )

    @lookup_handler.implicit_lookup
    def get_exit_status(self, connection=None):
        """Read an exit status of the previously sent command.

        See .send_command() for a documentation on the connection parameter.
        """
        connection = self._get_session_of(connection)
        status = connection.last_process.get_exit_code()
        logger.info("Last command's exit status was: %s", status)
        return status

    @lookup_handler.implicit_lookup
    def assert_exit_status(self, expected_exit_code, connection=None, msg=None):
        """Assert the exit status of the previously sent command.
        (Robot Framework keyword)

        If the exit code differs from the expected one, raises AssertionError.

        If parameter :code:`msg` is not supplied (is :code:`None`), default
        message is used, which looks like this::

            The exit code of the last command was: 1, expected: 0

        Optionally, the :code:`msg` parameter will be formatted with the last
        exit code and the expected one. If you wish to use this formatting, you
        can put :code:`{last}` and :code:`{expected}` in your message string
        (see example).

        Example::

            Assert Exit Status   0   connection=OAM   msg={last} != {expected}

        For a keyword that returns an exit code instead of asserting it, see
        :robot:kwrd:`Get Exit Status`.

        :param number expected_exit_code: anticipated exit code
        :param conref connection: (optional) connection to use
        :param string msg: (optional) exception message used in case of
            assertion failure
        """
        connection = self._get_session_of(connection)
        expected_exit_code = int(expected_exit_code)
        exit_code = connection.last_process.get_exit_code()

        if msg is None:
            msg = "The exit code of the last command was: {last}, "
            msg += "expected: {expected}."
        msg = msg.format(last=exit_code, expected=expected_exit_code)
        assert exit_code == expected_exit_code, msg

    @lookup_handler.implicit_lookup
    def get_exit_signal(self, connection=None):
        """Read an exit signal of the previously sent command.

        See .send_command() for a documentation on the connection parameter.

        :return: The exit signal of the last command, or None if the command
            did not exit via a signal.
        :rtype: str or None
        """
        connection = self._get_session_of(connection)
        signal = connection.last_process.get_exit_signal()
        logger.info("Last command's exit signal was: %s", signal)
        return signal

    @lookup_handler.implicit_lookup
    def execution_ended(self, connection=None):
        """Return True if an execution of the command ended, False otherwise.

        See .send_command() for a documentation on the connection parameter.
        """
        connection = self._get_session_of(connection)
        has_ended = not connection.last_process.is_alive()
        logger.info(
            "The execution of the last command %s.",
            "has ended" if has_ended else "has not ended",
        )

        return has_ended

    @lookup_handler.implicit_lookup
    def await_execution_end(self, connection=None, timeout=None):
        """Block until the command on the remote finished its execution.

        See .send_command() for a documentation on the connection parameter.

        :param timeout: (optional) Timeout for keyword execution, None by
            default. Accepts a timeout string in Robot Framework format.
            If None, waits for the command to end indefinitely.
        """
        connection = self._get_session_of(connection)
        logger.info("Blocking till the execution of the last command ends.")

        timeout = robot_typecasts.time_to_seconds(timeout)

        connection.last_process.join(timeout=timeout)

    @lookup_handler.implicit_lookup
    @ensure_connection
    def download_file(self, remote_path, local_path, connection=None, timeout=30):
        """Download file(s) from the remote.
        If remote_path is a single path (a string), then local_path must be a
        path to a file.
        If remote_path is a list of paths, then local_path must be a path to a
        directory.

        See .send_command() for a documentation on the connection parameter.
        """
        connection = self._get_session_of(connection)
        timeout = robot_typecasts.time_to_seconds(timeout)

        fp = connection.files
        single_path = isinstance(remote_path, str)

        if single_path:
            remote_path = [remote_path]
            full_local_paths = [local_path]
        else:
            self._verify_local_path_exists_and_is_dir(local_path)
            self._verify_remote_paths_exist_and_not_dir(remote_path, fp, timeout)

            full_local_paths = self._get_full_destination_paths(remote_path, local_path)

        logger.info("Downloading file(s) from %s", connection.address)
        for remote, local in zip(remote_path, full_local_paths):
            logger.info("Downloading remote file %r into local path %r", remote, local)
            fp.get(remote, local, timeout)

    @lookup_handler.implicit_lookup
    @ensure_connection
    def upload_file(self, local_path, remote_path, connection=None, timeout=30):
        """Upload file(s) to the remote.
        If local_path is a single path (a string), then remote_path must be a
        path to a file.
        If local_path is a list of paths, then remote_path must be a path to a
        directory.

        See .send_command() for a documentation on the connection parameter.
        """
        connection = self._get_session_of(connection)
        timeout = robot_typecasts.time_to_seconds(timeout)

        fp = connection.files
        single_path = isinstance(local_path, str)

        if single_path:
            local_path = [local_path]
            full_remote_paths = [remote_path]
        else:
            self._verify_remote_path_exists_and_is_dir(fp, remote_path, timeout)
            self._verify_local_paths_exist_and_not_dir(local_path)

            full_remote_paths = self._get_full_destination_paths(
                local_path, remote_path
            )

        logger.info("Uploading file(s) to %s", connection.address)
        for local, remote in zip(local_path, full_remote_paths):
            logger.info("Uploading local file %r to the remote at %r", local, remote)
            fp.put(local, remote, timeout)

    @lookup_handler.implicit_lookup
    @ensure_connection
    def file_exists(self, remote_path, connection=None, timeout=30):
        """Return True if file exists on the remote, False otherwise.

        This WILL follow symbolic links.
        See .send_command() for a documentation on the connection parameter.
        """
        connection = self._get_session_of(connection)
        timeout = robot_typecasts.time_to_seconds(timeout)

        exists = connection.files.exists(remote_path, timeout)

        logger.info(
            "File %s %s.", remote_path, "exists" if exists else "does not exist"
        )
        return exists

    @lookup_handler.implicit_lookup
    @ensure_connection
    def assert_file_exists(self, remote_path, connection=None, msg=None, timeout=30):
        """Assert an existance of a file on the remote.

        This WILL follow symbolic links.
        See .send_command() for a documentation on the connection parameter.
        """
        connection = self._get_session_of(connection)
        timeout = robot_typecasts.time_to_seconds(timeout)
        if msg is None:
            msg = "File '{path}' doesn't exist."

        msg = msg.format(path=remote_path)
        assert connection.files.exists(remote_path, timeout), msg

    @lookup_handler.implicit_lookup
    def force_reconnect(self, connection=None):
        """Try to disconnect and reconnect a connection instance."""
        connection = self._get_session_of(connection)
        connection.disconnect()
        keep_instance_connected(connection, warn=False)

    def reset_cache(self):
        """Close every connection and reset the cache."""
        self.connection_cache.close_connections()
        self.session_cache.close_connections()
        self.store.reset()

    @classmethod
    def _get_full_destination_paths(cls, source_file_paths, destination_dir_path):
        full_destination_paths = []
        for path in source_file_paths:
            full_destination_path = cls._get_destination_path(
                path, destination_dir_path
            )
            full_destination_paths.append(full_destination_path)

        return full_destination_paths

    @staticmethod
    def _get_destination_path(source_path, destination_dir_path):
        filename = os.path.basename(source_path)
        full_path = os.path.join(destination_dir_path, filename)
        return full_path

    @classmethod
    def _verify_remote_path_exists_and_is_dir(cls, fp, remote_path, timeout):
        try:
            remote_stat = fp.stat(remote_path, timeout)
            is_dir = stat.S_ISDIR(remote_stat.st_mode)
        except OSError:
            cls._raise_no_such_dir(remote_path)
        if not is_dir:
            cls._raise_not_dir(remote_path)

    @classmethod
    def _verify_local_path_exists_and_is_dir(cls, local_path):
        if not os.path.exists(local_path):
            cls._raise_no_such_dir(local_path)
        if not os.path.isdir(local_path):
            cls._raise_not_dir(local_path)

    @classmethod
    def _verify_remote_paths_exist_and_not_dir(cls, paths, fp, timeout):
        for path in paths:
            try:
                remote_stat = fp.stat(path, timeout)
                is_dir = stat.S_ISDIR(remote_stat.st_mode)
            except OSError:
                cls._raise_no_such_file(path)
            if is_dir:
                cls._raise_is_dir(path)

    @classmethod
    def _verify_local_paths_exist_and_not_dir(cls, paths):
        for path in paths:
            if not os.path.exists(path):
                cls._raise_no_such_file(path)
            elif os.path.isdir(path):
                cls._raise_is_dir(path)

    @staticmethod
    def _raise_no_such_dir(path):
        raise FileProtocolClientError(f"No such directory: {path}")

    @staticmethod
    def _raise_not_dir(path):
        raise FileProtocolClientError(f"Not a directory: {path}")

    @staticmethod
    def _raise_no_such_file(path):
        raise FileProtocolClientError(f"No such file: {path}.")

    @staticmethod
    def _raise_is_dir(path):
        raise FileProtocolClientError(f"Is a directory: {path}.")

    def get_connection_by_alias(self, alias):
        """Return a connection instance binded to the given alias."""
        return self._get_connection_object(self.store.get(alias))

    def _get_session_of(self, connection):
        if isinstance(connection, Connection):
            connection = self.session_cache.get_session(connection)
        return connection
